from pathlib import Pathfrom typing import Optional, Dict, Listimport pandas as pdimport loggingfrom pandas import DataFramefrom ..io.mapping_output import SWATOutputFileReader ,SWATReaderCachefrom ..io.file_cio import FileCIOfrom . txinout import TxInOutlogger = logging.getLogger(__name__)class SWATOutputManager:    def __init__(self, txinout: TxInOut):        self.txinout = txinout        self._cache = SWATReaderCache()        self._readers: Dict[str, SWATOutputFileReader] = {}    def _get_reader(self, file_type: str) -> Optional[SWATOutputFileReader]:        if file_type not in self._readers:            file_path = self.txinout.get_output_file(file_type)            self._readers[file_type] = SWATOutputFileReader(file_path, cache=self._cache)        return self._readers[file_type]    def read_rch(self, columns: Optional[str | list] = None) -> DataFrame:        if isinstance(columns, str):            columns = [columns]        return self._get_reader('.rch').read(columns)    def read_hru(self, columns: Optional[str | list] = None) -> DataFrame:        if isinstance(columns, str):            columns = [columns]        return self._get_reader('.hru').read(columns)    def read_sub(self, columns: Optional[str | list] = None) -> DataFrame:        if isinstance(columns, str):            columns = [columns]        return self._get_reader('.sub').read(columns)    def read_watout(self, columns: Optional[str | list] = None) -> DataFrame:        if isinstance(columns, str):            columns = [columns]        return self._get_reader('.dat').read(columns)    def __repr__(self):        cached = list(self._cache.keys())        return f"SWATOutputManager(cached={cached})"